<?php
declare(strict_types=1);
require_once __DIR__.'/../config/auth.php';
page_require(['ADMIN']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profesores — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:980px;margin:auto;padding:82px 14px 32px}.panel{background:#fff;border-radius:15px;padding:15px;margin:12px 0}.grid{display:grid;grid-template-columns:2fr 1.3fr 1.5fr auto;gap:8px}.grid input,.assign select{padding:10px;border:1px solid #cbd5e1;border-radius:9px;width:100%}.btn{border:0;border-radius:9px;padding:10px 12px;font-weight:800;cursor:pointer}.primary{background:#123b5d;color:#fff}.secondary{background:#e8eef2}.teacher{padding:12px 0;border-top:1px solid #e7edf4}.teacher:first-child{border-top:0}.top,.chips{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}.chip{background:#eef4f8;border-radius:999px;padding:7px 9px}.assign{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:9px}.muted{color:#64748b}.msg{min-height:22px;font-weight:800;color:#b42318}@media(max-width:700px){.grid,.assign{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Profesores</h1><p class="muted">Registra el WhatsApp del profe. Puedes asignarle varios horarios y también tener varios profes en el mismo horario.</p><div id="msg" class="msg" role="status"></div><section class="panel"><h2>Datos del profesor</h2><div class="grid"><input id="name" aria-label="Nombre" placeholder="Nombre"><input id="phone" aria-label="WhatsApp" placeholder="WhatsApp"><input id="email" aria-label="Correo opcional" type="email" placeholder="Correo opcional"><button id="save" class="btn primary">Guardar</button></div><input id="id" type="hidden"><label><input id="active" type="checkbox" checked> Activo</label> <button id="reset" class="btn secondary">Nuevo</button></section><section class="panel"><h2>Registrados</h2><div id="list">Cargando…</div></section></main><script>
const byId=x=>document.getElementById(x),msg=byId('msg'),list=byId('list');let model={profesores:[],horarios:[],csrf:''};const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function post(body){const r=await fetch('/api/profesores.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,csrf:model.csrf})}),d=await r.json();if(r.status===419){await load();throw new Error(d.error||'Sesión de seguridad vencida. Recarga la página.')}if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}function note(t){msg.textContent=t}function clear(){byId('id').value='';byId('name').value='';byId('phone').value='';byId('email').value='';byId('active').checked=true}function label(h){return h.sede_nombre+' · '+String(h.hora_inicio).slice(0,5)+'–'+String(h.hora_fin).slice(0,5)}
function draw(){list.innerHTML=model.profesores.map(p=>{const active=(p.horarios||[]).filter(h=>Number(h.activo)===1),used=new Set(active.map(h=>h.horario_id)),opts=model.horarios.filter(h=>!used.has(h.id)).map(h=>'<option value="'+esc(h.id)+'">'+esc(label(h))+'</option>').join(''),chips=active.map(h=>'<span class="chip">'+esc(label(h))+' <button type="button" aria-label="Quitar '+esc(label(h))+'" data-off="'+esc(p.id)+'::'+esc(h.horario_id)+'">×</button></span>').join('')||'<span class="muted">Sin horarios</span>';return '<div class="teacher"><div class="top"><div><strong>'+esc(p.nombre)+(Number(p.activo)===1?'':' (inactivo)')+'</strong><div class="muted">'+esc(p.whatsapp)+'</div></div><button type="button" class="btn secondary" data-edit="'+esc(p.id)+'">Editar</button></div><div class="chips">'+chips+'</div><div class="assign"><select aria-label="Asignar horario a '+esc(p.nombre)+'" data-sel="'+esc(p.id)+'"><option value="">Selecciona una clase/horario…</option>'+opts+'</select><button type="button" class="btn primary" data-on="'+esc(p.id)+'">Asignar</button></div></div>'}).join('')||'<p class="muted">Todavía no hay profesores.</p>';list.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const p=model.profesores.find(x=>x.id===b.dataset.edit);byId('id').value=p.id;byId('name').value=p.nombre;byId('phone').value=p.whatsapp;byId('email').value=p.correo||'';byId('active').checked=Number(p.activo)===1});list.querySelectorAll('[data-on]').forEach(b=>b.onclick=async()=>{const box=b.closest('.assign'),s=box?box.querySelector('[data-sel]'):null;if(!s){note('No pude localizar el selector de horario. Recarga la página e inténtalo de nuevo.');return}const schedule=String(s.value||'').trim();if(schedule===''){note('Selecciona primero una clase u horario.');s.focus();return}const original=b.textContent;b.disabled=true;b.textContent='Asignando…';note('Asignando horario…');try{await post({accion:'ASSIGN',profesor_id:b.dataset.on,horario_id:schedule,activo:true});note('Horario asignado correctamente.');await load()}catch(e){note(e.message||'No se pudo asignar el horario.')}finally{if(document.body.contains(b)){b.disabled=false;b.textContent=original}}});list.querySelectorAll('[data-off]').forEach(b=>b.onclick=async()=>{const parts=b.dataset.off.split('::');try{await post({accion:'ASSIGN',profesor_id:parts[0],horario_id:parts[1],activo:false});note('Horario retirado.');await load()}catch(e){note(e.message)}})}
async function load(){try{const r=await fetch('/api/profesores.php',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar');model=d;draw()}catch(e){note(e.message)}}byId('save').onclick=async()=>{try{await post({accion:'SAVE',id:byId('id').value,nombre:byId('name').value,whatsapp:byId('phone').value,correo:byId('email').value,activo:byId('active').checked});clear();note('Profesor guardado.');await load()}catch(e){note(e.message)}};byId('reset').onclick=clear;load();
</script></body></html>
